sp_widget.client_script:
function($scope, $rootScope, $location, spUtil, spModal, $timeout) {
	var c = this;
	var selectedElement = null;

	// add a new file tab when a file type is selected
	c.onNewFileSelect = function(file_type) {
		c.server.get({
			action: 'getFileInfo',
			file_type: file_type
		}).then(function(result) {
			document.getElementById('new_file_picker').value = '';
			c.addTab(result.data.file_info, -1, 'New File');
		});	
	}	

	// refresh the file tree
	// ToDo: need to figure out how to auto-refresh
	c.refresh = function() {
		spUtil.update($scope);
	}

	c.filetype = {
		displayValue: c.data.set_name,
		value: c.data.set_sysid, 
		name: 'updateset'	
	}

	c.addTab = function(table_name, sys_id, file_name) {
		// highlight the selected file
		// var clickedElement = document.getElementById(sys_id);
		// if (selectedElement) selectedElement.classList.remove('selected');		
		// clickedElement.classList.add('selected');
		// selectedElement = clickedElement;

		var obj = {
			id: 'update_set_studio',
			sys_id: sys_id,
			table: table_name,
			file_name: file_name
		};

		$rootScope.$broadcast('addTabEvent', obj);
	}


	/***********************************************
	Code for a potential update set picker. I stuck it here to get it out of the way.

	The sn-record-picker below would, of course, go in the HTML

      <sn-record-picker style="display: none;" id="updateset" field="c.updateset" table="'sys_update_set'"
                        display-field="'name'"
                        value-field="'sys_id'" 
                        search-fields="name" page-size="100" on-change="onChange()"></sn-record-picker>

	// obviously this listener needs work	
	// listen for update set changes
	$scope.$on("field.change", function(evt, parms) {
		if (parms.field.name == 'updateset') {
			//if (parms.field.newValue != parms.field.oldValue) {
			//console.log(JSON.stringify(parms));

			c.server.get({
				action: 'change_update_set',
				updateset: c.updateset.value,
			}).then(function(response) {
				console.log(response.data.retdata);
			});		
			//}
		}
	});
	************************************************/	
}

sp_widget.css:
#XXtop {
  padding: 15px; 
  max-height: 100%;
  min-height: 100%;
  height: 100%;
}

.set-info {
  font-size: 1.5rem; 
}

.new-file {
  font-size: 1.65rem;
  font-weight: 900;
  color: #00adb5;
}

#new_file_picker {
  width: 95%;
  font-size: 1.2rem;
  color: #222;
  background: #fff;
  border-color: #fff;
  border-radius: 4px;
  padding-left: 5px;
}

#refresh {
  color: #aaa;
  font-size: 2rem; 
}

#refresh:hover {
  color: #fff;
  cursor: pointer; 
}

.new-file-container {
  display: flex;
  flex-direction: row;
  width: 100%;
  height: 40px;
  margin-top: 10px;
  align-items: center;
}

.selected {
  font-weight: 100;
  font-style: italic;
}

summary { 
  cursor: pointer; 
  font-weight: 700;
}

.tree {
  position: relative;
  margin-top: .5rem;
  font-weight: 400;
  line-height: 1.2;
  color: #ddd;

  ul {
    padding-left: 5px;
    list-style: none;
    letter-spacing: -1px;

    li {
      position: relative;
      padding-top: 5px;
      padding-bottom: 0;
      padding-left: 15px;
      box-sizing: border-box;
      user-select: none;
      letter-spacing: -1px;

      &:before {
        position: absolute;
        top: 15px;
        left: 0;
        width: 10px;
        height: 1px;
        margin: auto;
        content: '';
        background-color: #ccc;
      }

      &:after {
        position: absolute;
        top: 0;
        bottom: 0;
        left: 0;
        width: 1px;
        height: 100%;
        content: '';
        background-color: #ccc;
      }

      &:last-child:after {
        height: 15px;
      }
    }
  }
}

sp_widget.script:
(function() {
	var au = new ArrayUtil();
	var current_set = (new GlideUpdateSet()).get();
	var set_info = getSetInfo(current_set);
	var set  = [];
	var folders = getFolders(current_set);

	data.set_name = set_info.name;
	data.set_scope = set_info.app_scope;
	data.set_sysid = set_info.sysid;
	data.retdata = set_info.name;
	data.selectedRecords = [];

	if (input) {
		if (input.action == 'getFileInfo') {
			data.file_info = getFileInfo(input.file_type);
		}
	}

	var gr = new GlideAggregate('sys_update_xml'); 
	gr.groupBy('type'); 
	gr.query(); 

	while (gr.next()) { 
		data.selectedRecords.push(gr.getValue('type')); 
	} 	


	// get the files for each folder type
	folders.forEach(function(folder) {
		var o = {};
		o.folder = folder;
		o.files = getFiles(current_set, folder);
		set.push(o);
	});

	data.folders = set;

	function getFileInfo(file_type) {
		var gr = new GlideRecord('sys_update_xml');
		gr.addEncodedQuery('type=' + file_type);
		gr.setLimit(1);
		gr.query();

		var files = [];
		if (gr.next()) {
			var name = gr.getValue('name');
			var o = {};

			try {
				// get the update's table and sys_id from the payload
				var payload = gr.payload;
				var xmlDoc = new XMLDocument2();
				xmlDoc.parseXML(payload);

				o.table_name = (xmlDoc.getFirstNode('//sys_class_name')).getTextContent();
				return o.table_name;

			} catch (err) {
				//console.log('GUSS: Failed to load ' + name);
			} finally {
				files.push(o);
			}
		}

		return files;
	}

	function getFolders(update_set) {
		var gr = new GlideRecord('sys_update_xml');
		//gr.addEncodedQuery('update_set=' + update_set + '^typeIN' + options.file_types_display);
		gr.addEncodedQuery('update_set=' + update_set);
		gr.orderBy('type');
		gr.query();

		var folders = [];
		while (gr.next()) {
			var type = gr.getValue('type');

			if (!au.contains(folders, type)) {
				folders.push(type);
			}	
		}

		return folders;
	}

	function getFiles(update_set, type) {
		var gr = new GlideRecord('sys_update_xml');
		gr.addEncodedQuery('update_set=' + update_set + '^type=' + type + '^action!=delete');
		gr.orderBy('target_name');
		gr.query();	

		var files = [];
		while (gr.next()) {
			var name = gr.getValue('name');
			var o = {};

			try {
				// get the update's table and sys_id from the payload
				var payload = gr.payload;
				var xmlDoc = new XMLDocument2();
				xmlDoc.parseXML(payload);

				o.target_name = gr.getValue('target_name');
				o.table_name = (xmlDoc.getFirstNode('//sys_class_name')).getTextContent();
				o.sys_id = (xmlDoc.getFirstNode('//sys_id')).getTextContent();
				o.file_name = getFileName(o.table_name, o.sys_id);					
			}
			catch(err) {
				console.log('GUSS: Failed to load ' + name);
			}
			finally {
				files.push(o);	
			}
		}

		return files;
	}

	function getSetInfo(set) {
		var gr = new GlideRecord('sys_update_set');
		if (gr.get(set)) {
			return { name: gr.getValue('name'),
							app_scope: gr.getValue('application'),
							sysid: gr.getValue('sys_id') };
		}

		return false;
	}

	function getTypes() {
		var gr = new GlideRecord('sys_update_xml');
		gr.addEncodedQuery('update_set', current_set);
		gr.orderBy('type');
		gr.query();

		var types = [];
		while (gr.next()) {
			var t = gr.getValue('type');

			if (!au.contains(log, t)) {
				types.push(t);
			}

		}

		return types;
	}

	function getFileName(table, sys_id) {
		var gr = new GlideRecord(table);
		if (gr.get(sys_id)) {
			return gr.getDisplayValue();
		}
	}

})();

sp_widget.client_script:
api.controller=function($scope, $rootScope, $timeout) {
	var c = this;

	$scope.tabs = [];
	$scope.activeTabIndex = 0;	

	c.setActiveTab = function(index) {
		$scope.activeTabIndex = index;
	};

	$scope.removeTab = function(index) {
		$scope.tabs.splice(index, 1);

		// set active tab to the previous index
		if ($scope.tabs.length > 0) {
			if (index == 0) $scope.activeTabIndex = index;
			else $scope.activeTabIndex = index - 1;
		}
		else {
			$rootScope.$broadcast('removeTabEvent', index);

			// show title screen
			document.getElementById('title-screen').style.display = 'flex';
		}		
	};

	$rootScope.$on('addTabEvent', function(event, obj) {
		event.preventDefault();

		// hide title screen
		document.getElementById('title-screen').style.display = 'none';

		// don't display if the file is already opened in a tab
		var tab_found = false;
		for (var i=0; i<$scope.tabs.length; i++) {
			if ($scope.tabs[i].file_name == obj.file_name) {
				// set as active tab
				$scope.activeTabIndex = i;
				tab_found = true;
				break;
			}
		}

		if (!tab_found) {			
			$scope.tabs.push(obj);

			$timeout(function() {
				$scope.activeTabIndex = $scope.tabs.length - 1;
				var iframe = document.createElement("iframe");
				iframe.id = 'iframe' + Math.random().toString(36).substring(2,8);
				iframe.frameborder = 0;
				iframe.classList.add('height-100');

				var target = '/${table}.do?sys_id=${sysid}&sysparm_record_target=${table}&sysparm_record_list=sys_class_name%3D${table}&sysparm_isdevstudio=true';
				target = target.replaceAll('${table}', obj.table).replaceAll('${sysid}', obj.sys_id);			

				iframe.src = target;

				document.getElementById('content-' + obj.file_name).appendChild(iframe);

				// wait for the iframe to load and do stuff
				iframe.addEventListener('load', function() {
					// hide the form's back button and arrows
					this.contentWindow.document.getElementsByClassName('btn btn-default icon-chevron-left navbar-btn')[0].style.display = 'none';
					this.contentWindow.document.getElementsByClassName('icon-arrow-up')[0].style.display = 'none';
					this.contentWindow.document.getElementsByClassName('icon-arrow-down')[0].style.display = 'none';	

					this.contentWindow.document.addEventListener('click', function(event) {
						// we're trying to listen for the Save button to be clicked
						// problem is that the Save button isn't default on many forms
						// this is a ToDo item
					});						
				});
			});	
		}

	});

};

